```ts
interface PriceObserver {
  onPriceChanged(price: number): void;
}

class StockPrice {
  private observers: PriceObserver[] = [];
  private price = 0;

  subscribe(o: PriceObserver) { this.observers.push(o); }
  unsubscribe(o: PriceObserver) {
    this.observers = this.observers.filter(x => x !== o);
  }
  setPrice(newPrice: number) {
    this.price = newPrice;
    for (const o of this.observers) o.onPriceChanged(newPrice);
  }
}

class PriceChart implements PriceObserver {
  onPriceChanged(price: number) { /* redraw chart */ }
}

const aapl = new StockPrice();
aapl.subscribe(new PriceChart());
aapl.setPrice(191.20);   // PriceChart redraws; StockPrice never named it
```

`StockPrice` never imports `PriceChart` — it only knows the `PriceObserver` interface. Any object implementing it can subscribe, including ones written after `StockPrice` shipped.
